WebTerminalUrl.description_en:
The WebSocket link for accessing the container. You need to build a WebSocket client. For the detailed communication format, refer to the following code:
  ```
  ws = new WebSocket(
    `wss://xxxxx`,
  );
  ws.onopen = function open() {
    console.warn('connected');
    term.write('');
  };

  ws.onclose = function close() {
    console.warn('disconnected');
    term.write('Connection closed');
  };

  // Receive response from the backend
  ws.onmessage = function incoming(event) {
    const msg = JSON.parse(event.data);
    console.warn(msg);
    if (msg.operation === 'stdout') {
      term.write(msg.data);
    } else {
      console.warn('invalid msg operation: ' + msg);
    }
  };

  // Console input
  term.onData(data => {
    const msg = { operation: 'stdin', data: data };
    ws.send(JSON.stringify(msg));
  });

  term.onResize(size => {
    const msg = { operation: 'resize', cols: size.cols, rows: size.rows };
    ws.send(JSON.stringify(msg));
  });

  fitAddon.fit();
};
```

WebTerminalUrl.description_zh:
进入容器的WebSocket链接。您需构建WebSocket客户端，详细通信格式请参考如下代码：
  ```
  ws = new WebSocket(
    `wss://xxxxx`,
  );
  ws.onopen = function open() {
    console.warn('connected');
    term.write('\r');
  };

  ws.onclose = function close() {
    console.warn('disconnected');
    term.write('Connection closed');
  };

  // 收到后端返回
  ws.onmessage = function incoming(event) {
    const msg = JSON.parse(event.data);
    console.warn(msg);
    if (msg.operation === 'stdout') {
      term.write(msg.data);
    } else {
      console.warn('invalid msg operation: ' + msg);
    }
  };

  // 控制台输入
  term.onData(data => {
    const msg = { operation: 'stdin', data: data };
    ws.send(JSON.stringify(msg));
  });

  term.onResize(size => {
    const msg = { operation: 'resize', cols: size.cols, rows: size.rows };
    ws.send(JSON.stringify(msg));
  });

  fitAddon.fit();
};
```
